-- 04-ga-improve-b1-prepay 只讀驗證（G1 預付款）：每列回 pass 或 fail，全部 pass 才算套用成功。只有 SELECT，沒有任何寫入。
SELECT '資料表 ga_payment_prepay_ledger 存在' AS check_name, CASE WHEN to_regclass('public.ga_payment_prepay_ledger') IS NOT NULL THEN 'pass' ELSE 'fail' END AS result
UNION ALL
SELECT '資料表 ga_payment_prepay_ledger 開啟 RLS 且不開放給登入者與匿名' AS check_name, CASE WHEN COALESCE((SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.ga_payment_prepay_ledger')), false) AND NOT has_table_privilege('authenticated', 'public.ga_payment_prepay_ledger', 'SELECT') AND NOT has_table_privilege('anon', 'public.ga_payment_prepay_ledger', 'SELECT') THEN 'pass' ELSE 'fail' END AS result
UNION ALL
SELECT '欄位 ga_payment_requests.pay_kind 存在' AS check_name, CASE WHEN EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'ga_payment_requests' AND column_name = 'pay_kind') THEN 'pass' ELSE 'fail' END AS result
UNION ALL
