SELECT '請款事件類型約束是超集（含 prepay_refund，舊值都保留）' AS check_name, CASE WHEN EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ga_payment_request_events_type_check' AND pg_get_constraintdef(oid) LIKE '%prepay_refund%' AND pg_get_constraintdef(oid) LIKE '%refresh_bank%' AND pg_get_constraintdef(oid) LIKE '%mark_paid%') THEN 'pass' ELSE 'fail' END AS result
UNION ALL
